// DESIGN (pure model, no DOM)
// Phenomenon: a ray of monochromatic light meets a flat boundary between two media.
// Equations: law of reflection θr = θ1; Snell n1 sin θ1 = n2 sin θ2;
// critical angle θc = asin(n2/n1) if n1 > n2; Fresnel coefficients (s, p),
// unpolarized R = (Rs+Rp)/2, T = 1 - R computed independently from t-coefficients.
// Brewster θB = atan(n2/n1). Pulse speed in medium v = c/n.
// Bounds: θ1 ∈ [0°, 89°]; n1, n2 ∈ [1.00, 2.50] (dimensionless).
// Simplifications: plane wave treated as a ray; flat, smooth, infinite interface;
// homogeneous, isotropic, linear, non-absorbing, non-magnetic (μ = μ0) media;
// single wavelength (no dispersion); unpolarized light = average of s and p.
// Visual layers: medium bands, normal, rays (opacity ∝ power), angle arcs, pulses.
// Camera: fixed 2D section, interface horizontal, incidence point at centre.

export const LIMITS = { theta: [0, 89], n: [1, 2.5] };
export const PRESETS = {
  'ar-vidro': { n1: 1.0, n2: 1.52, label: 'Ar → vidro' },
  'vidro-ar': { n1: 1.52, n2: 1.0, label: 'Vidro → ar' },
  'agua-ar': { n1: 1.33, n2: 1.0, label: 'Água → ar' },
  'ar-agua': { n1: 1.0, n2: 1.33, label: 'Ar → água' },
};
export const DEG = Math.PI / 180;
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));

export function solve(n1, n2, thetaDeg) {
  n1 = clamp(+n1, ...LIMITS.n); n2 = clamp(+n2, ...LIMITS.n);
  const th1 = clamp(+thetaDeg, ...LIMITS.theta) * DEG;
  const ci = Math.cos(th1), s2 = (n1 / n2) * Math.sin(th1);
  const critical = n1 > n2 ? Math.asin(n2 / n1) / DEG : null;
  const brewster = Math.atan(n2 / n1) / DEG;
  if (s2 > 1) {
    return { n1, n2, theta1: th1 / DEG, theta2: null, tir: true, critical, brewster,
      Rs: 1, Rp: 1, R: 1, T: 0, Ts: 0, Tp: 0, invariant: n1 * Math.sin(th1) };
  }
  const th2 = Math.asin(s2), ct = Math.cos(th2);
  const rs = (n1 * ci - n2 * ct) / (n1 * ci + n2 * ct);
  const rp = (n2 * ci - n1 * ct) / (n2 * ci + n1 * ct);
  const ts = (2 * n1 * ci) / (n1 * ci + n2 * ct);
  const tp = (2 * n1 * ci) / (n2 * ci + n1 * ct);
  const k = (n2 * ct) / (n1 * ci);
  const Rs = rs * rs, Rp = rp * rp, Ts = k * ts * ts, Tp = k * tp * tp;
  return { n1, n2, theta1: th1 / DEG, theta2: th2 / DEG, tir: false, critical, brewster,
    Rs, Rp, R: (Rs + Rp) / 2, T: (Ts + Tp) / 2, Ts, Tp, invariant: n1 * Math.sin(th1) };
}

// Unit direction vectors in diagram coordinates (x right, y DOWN, interface y=0,
// medium 1 above). Normal along y.
export function rays(sol) {
  const a = sol.theta1 * DEG;
  const inc = [Math.sin(a), Math.cos(a)];          // travelling toward O
  const refl = [Math.sin(a), -Math.cos(a)];        // leaving O, upward
  const trans = sol.tir ? null : [Math.sin(sol.theta2 * DEG), Math.cos(sol.theta2 * DEG)];
  return { inc, refl, trans };
}

// Pulses: path length L = 1 per ray, c = 1. A pulse emitted at τ0 spends n1 on
// the incident ray, then splits: reflected (speed 1/n1), transmitted (speed 1/n2).
export const PERIOD = 1.25;
export function pulses(sol, tau) {
  const out = [], life = sol.n1 + Math.max(sol.n1, sol.n2);
  const kMax = Math.floor(tau / PERIOD), kMin = Math.max(0, Math.ceil((tau - life) / PERIOD));
  for (let k = kMin; k <= kMax; k++) {
    const age = tau - k * PERIOD;
    if (age < 0) continue;
    if (age < sol.n1) { out.push({ ray: 'inc', s: age / sol.n1, power: 1, id: k }); continue; }
    const after = age - sol.n1;
    const sr = after / sol.n1;
    if (sr <= 1 && sol.R > 1e-4) out.push({ ray: 'refl', s: sr, power: sol.R, id: k });
    const st = after / sol.n2;
    if (!sol.tir && st <= 1 && sol.T > 1e-4) out.push({ ray: 'trans', s: st, power: sol.T, id: k });
  }
  return out;
}

export function createState() { return { theta: 30, n1: 1.0, n2: 1.52, tau: 2.5, playing: false }; }
export function setParam(state, key, v) {
  const lim = key === 'theta' ? LIMITS.theta : LIMITS.n;
  const x = clamp(Number(v), ...lim);
  return Number.isFinite(x) ? { ...state, [key]: x } : state;
}
export function applyPreset(state, id) { const p = PRESETS[id]; return p ? { ...state, n1: p.n1, n2: p.n2 } : state; }
export function swap(state) { return { ...state, n1: state.n2, n2: state.n1 }; }
export const SPEED = 0.7; // τ units per second of wall time
export function step(state, dt) {
  if (!state.playing) return state;
  return { ...state, tau: (state.tau + clamp(dt, 0, 0.1) * SPEED) % 1000 };
}
export function regime(sol) {
  if (sol.tir) return 'Reflexão interna total';
  if (Math.abs(sol.n1 - sol.n2) < 1e-9) return 'Meios iguais: sem desvio';
  if (sol.theta1 < 0.05) return 'Incidência normal';
  return 'Refração parcial';
}
export const fmt = (x, d = 1) => x.toFixed(d).replace('.', ',');

checks:
import { solve, rays, pulses, createState, step, setParam, swap, regime, PERIOD } from './model.mjs';

const near = (a, b, e = 1e-9) => Math.abs(a - b) <= e;

export function verify() {
  const out = [];
  const add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  const ns = [1, 1.2, 1.33, 1.52, 2.0, 2.42, 2.5];

  let snell = true, energy = true, refl = true, worst = '';
  for (const n1 of ns) for (const n2 of ns) for (let t = 0; t <= 89; t += 0.5) {
    const s = solve(n1, n2, t);
    if (!s.tir) {
      if (!near(n1 * Math.sin(s.theta1 * Math.PI / 180), n2 * Math.sin(s.theta2 * Math.PI / 180), 1e-9)) { snell = false; worst = `${n1},${n2},${t}`; }
      if (!near(s.Rs + s.Ts, 1, 1e-9) || !near(s.Rp + s.Tp, 1, 1e-9)) { energy = false; worst = `${n1},${n2},${t}`; }
    }
    const r = rays(s);
    if (!near(r.refl[0], r.inc[0]) || !near(r.refl[1], -r.inc[1])) refl = false;
  }
  add('Lei de Snell em todo o domínio amostrado', snell, worst);
  add('Conservação: Rs+Ts=1 e Rp+Tp=1 (sem absorção)', energy, worst);
  add('Lei da reflexão: θr = θ1 (espelho na normal)', refl);

  let tirOk = true;
  for (const n1 of ns) for (const n2 of ns) for (let t = 0; t <= 89; t += 0.25) {
    const s = solve(n1, n2, t);
    const expect = n1 > n2 && Math.sin(t * Math.PI / 180) > n2 / n1;
    if (s.tir !== expect) tirOk = false;
    if (s.tir && (s.R !== 1 || s.T !== 0)) tirOk = false;
    if (n1 <= n2 && s.critical !== null) tirOk = false;
  }
  add('RIT só ocorre se n1>n2 e θ1>θc; então R=1', tirOk);

  const a = solve(1.52, 1, 41.0), b = solve(1.52, 1, 41.3);
  add('Transição em θc ≈ 41,1° (vidro→ar)', !a.tir && b.tir && near(a.critical, 41.14, 0.01), `θc=${a.critical}`);

  const s0 = solve(1, 1.52, 0);
  add('Incidência normal: R=((n1-n2)/(n1+n2))²', near(s0.R, (0.52 / 2.52) ** 2, 1e-12) && near(s0.theta2, 0, 1e-12));

  const eq = solve(1.33, 1.33, 57);
  add('Meios iguais: sem desvio nem reflexão', near(eq.theta2, 57, 1e-9) && eq.R < 1e-20 && regime(eq).includes('sem desvio'));

  const br = solve(1, 1.52, solve(1, 1.52, 0).brewster);
  add('Ângulo de Brewster: Rp = 0', br.Rp < 1e-20 && br.Rs > 0.1, `Rp=${br.Rp}`);

  const f = solve(1, 1.52, 50), back = solve(1.52, 1, f.theta2);
  add('Reversibilidade do caminho óptico', near(back.theta2, 50, 1e-9) && near(back.R, f.R, 1e-12));

  let graze = solve(1, 1.52, 89);
  add('Ar→vidro rasante: θ2 < θc inverso, sem RIT', !graze.tir && graze.theta2 < solve(1.52, 1, 0).critical);

  // pulse kinematics: continuity at O and speed ratio
  const s = solve(1, 2, 30);
  const before = pulses(s, 1 - 1e-6).find(p => p.id === 0);
  const after = pulses(s, 1 + 1e-6).filter(p => p.id === 0);
  add('Pulso contínuo no ponto de incidência', before.ray === 'inc' && before.s > 0.9999 && after.some(p => p.ray === 'refl' && p.s < 1e-5) && after.some(p => p.ray === 'trans' && p.s < 1e-5));
  const later = pulses(s, 1.5).filter(p => p.id === 0);
  const pr = later.find(p => p.ray === 'refl'), pt = later.find(p => p.ray === 'trans');
  add('Velocidade c/n: transmitido em n=2 anda metade', near(pt.s / pr.s, 0.5, 1e-9));
  const tir = solve(1.52, 1, 60);
  let none = true;
  for (let t = 0; t < 10; t += 0.05) if (pulses(tir, t).some(p => p.ray === 'trans')) none = false;
  add('Em RIT nenhum pulso é transmitido', none);

  let st = { ...createState(), playing: true }; const t0 = st.tau;
  for (let i = 0; i < 60; i++) st = step(st, 1 / 60);
  const paused = step({ ...st, playing: false }, 1);
  add('Tempo avança ao reproduzir e para em pausa', st.tau > t0 + 0.5 && paused.tau === st.tau);
  const cl = setParam(createState(), 'theta', 120), cn = setParam(createState(), 'n1', 0.3);
  add('Parâmetros limitados ao domínio', cl.theta === 89 && cn.n1 === 1);
  const sw = swap(createState());
  add('Trocar meios inverte n1 e n2', sw.n1 === 1.52 && sw.n2 === 1);
  add('Período de pulsos positivo', PERIOD > 0 && pulses(solve(1, 1, 0), 0).length === 1);
  return out;
}

