import { createState, setParam, applyPreset, swap, step, solve, regime, fmt, PRESETS, LIMITS } from './model.mjs';
import { drawScene, drawPulses, VIEW } from './geometry.mjs';

export function mount(root, env = {}) {
  let st = createState();
  let reduced = !!env.reducedMotion, visible = true, raf = 0, last = 0;
  const rng = (id, label, min, max, stepv, val, unit) => `
    <label class="ctl" for="${id}"><span>${label}</span>
      <input id="${id}" type="range" min="${min}" max="${max}" step="${stepv}" value="${val}">
      <output id="${id}-out">${unit(val)}</output></label>`;
  root.innerHTML = `<div class="rf">
    <div class="rf-art"><svg viewBox="0 0 ${VIEW.w} ${VIEW.h}" role="img" aria-label="Raios incidente, refletido e transmitido na fronteira entre dois meios">
      <g id="scene"></g><g id="pulses"></g></svg></div>
    <div class="rf-side">
      <p class="status" aria-live="polite"><span id="status"></span></p>
      <div class="ctls">
        ${rng('theta', 'Ângulo de incidência θ₁', LIMITS.theta[0], LIMITS.theta[1], 0.5, st.theta, (v) => fmt(+v) + '°')}
        ${rng('n1', 'Índice n₁ (meio 1)', 1, 2.5, 0.01, st.n1, (v) => fmt(+v, 2))}
        ${rng('n2', 'Índice n₂ (meio 2)', 1, 2.5, 0.01, st.n2, (v) => fmt(+v, 2))}
      </div>
      <div class="btns">
        ${Object.entries(PRESETS).map(([k, p]) => `<button type="button" id="preset-${k}">${p.label}</button>`).join('')}
      </div>
      <div class="btns">
        <button type="button" id="play" class="primary">Reproduzir</button>
        <button type="button" id="advance">Avançar</button>
        <button type="button" id="swap">Trocar meios</button>
        <button type="button" id="reset">Reiniciar</button>
      </div>
      <p class="note" id="note"></p>
      <dl class="read">
        <dt>Lei de Snell</dt><dd id="snell"></dd>
        <dt>Ângulo refratado θ₂</dt><dd id="theta2"></dd>
        <dt>Ângulo crítico θc</dt><dd id="critical"></dd>
        <dt>Reflexão / transmissão</dt><dd id="rt"></dd>
        <dt>Ângulo de Brewster</dt><dd id="brewster"></dd>
      </dl>
      <details><summary>Equações e simplificações</summary>
        <p>n₁ sen θ₁ = n₂ sen θ₂ · θᵣ = θ₁ · θc = arcsen(n₂/n₁) se n₁ &gt; n₂ · v = c/n.</p>
        <p>R e T são médias de Fresnel (s e p) para luz não polarizada; R + T = 1.</p>
        <ul><li>Onda plana monocromática tratada como raio; sem dispersão.</li>
        <li>Fronteira plana, lisa e infinita; meios homogêneos, isotrópicos, sem absorção e não magnéticos.</li>
        <li>Na reflexão interna total, o campo evanescente (que não transporta energia) não é desenhado.</li>
        <li>Índices dos atalhos são aproximados (≈589 nm).</li></ul>
      </details>
    </div></div>`;
  const $ = (s) => root.querySelector(s);
  const scene = $('#scene'), pl = $('#pulses');
  let sol = solve(st.n1, st.n2, st.theta);

  function update() {
    sol = solve(st.n1, st.n2, st.theta);
    for (const k of ['theta', 'n1', 'n2']) {
      const inp = $('#' + k); if (+inp.value !== st[k]) inp.value = st[k];
      $('#' + k + '-out').textContent = k === 'theta' ? fmt(st.theta) + '°' : fmt(st[k], 2);
    }
    scene.innerHTML = drawScene(sol);
    const reg = regime(sol);
    $('#status').textContent = reg;
    $('#status').parentElement.dataset.tir = sol.tir ? '1' : '0';
    const lhs = fmt(sol.invariant, 3);
    $('#snell').textContent = sol.tir
      ? `n₁ sen θ₁ = ${lhs} > n₂ = ${fmt(sol.n2, 2)} → sen θ₂ > 1`
      : `${fmt(sol.n1, 2)} × sen ${fmt(sol.theta1)}° = ${lhs} = ${fmt(sol.n2, 2)} × sen ${fmt(sol.theta2)}°`;
    $('#theta2').textContent = sol.tir ? 'não existe (reflexão interna total)' : `${fmt(sol.theta2)}°`;
    $('#critical').textContent = sol.critical === null ? 'não existe (n₁ ≤ n₂): RIT impossível' : `${fmt(sol.critical)}°`;
    $('#rt').textContent = `R = ${fmt(100 * sol.R)} % · T = ${fmt(100 * sol.T)} %`;
    $('#brewster').textContent = `${fmt(sol.brewster)}° (Rp = 0)`;
    drawP();
  }
  const drawP = () => { pl.innerHTML = drawPulses(sol, st.tau); };
  function frame(t) {
    raf = 0;
    if (!st.playing || !visible) return;
    const dt = last ? (t - last) / 1000 : 0; last = t;
    st = step(st, dt); drawP();
    raf = requestAnimationFrame(frame);
  }
  function startLoop0() {}
  function stopLoop() { if (raf) cancelAnimationFrame(raf); raf = 0; }
  function setPlaying(p) {
    st = { ...st, playing: p };
    $('#play').textContent = p ? 'Pausar' : 'Reproduzir';
    $('#play').setAttribute('aria-pressed', p ? 'true' : 'false');
    if (p) {
      if (reduced) { st = { ...st, tau: st.tau + 0.4 }; drawP(); $('#note').textContent = 'Movimento reduzido: use “Avançar” para mover os pulsos.'; }
      else startLoop();
    } else stopLoop();
  }
  function startLoop() { if (!raf && st.playing && visible && !reduced) { last = 0; raf = requestAnimationFrame(frame); } }
  const on = (sel, ev, fn) => $(sel).addEventListener(ev, fn);
  for (const k of ['theta', 'n1', 'n2']) on('#' + k, 'input', (e) => { st = setParam(st, k, e.target.value); update(); });
  for (const k of Object.keys(PRESETS)) on('#preset-' + k, 'click', () => { st = applyPreset(st, k); update(); });
  on('#swap', 'click', () => { st = swap(st); update(); });
  on('#reset', 'click', () => { stopLoop(); st = createState(); setPlaying(false); update(); });
  on('#play', 'click', () => setPlaying(!st.playing));
  on('#advance', 'click', () => { st = { ...st, tau: st.tau + 0.25 }; drawP(); });
  const envH = (e) => {
    const d = e.detail || {};
    if ('reducedMotion' in d) { reduced = !!d.reducedMotion; if (reduced) stopLoop(); else startLoop(); }
    if ('visible' in d) { visible = d.visible !== false; visible ? startLoop() : stopLoop(); }
  };
  root.addEventListener('figure:environment', envH);
  update();
  return () => { stopLoop(); root.removeEventListener('figure:environment', envH); root.innerHTML = ''; };
}

