import { rays, pulses, fmt, DEG } from './model.mjs';

export const VIEW = { w: 400, h: 360, ox: 200, oy: 180, L: 140 };
const { ox, oy, L } = VIEW;
const f = (v) => +v.toFixed(2);
const pt = (p) => `${f(p[0])},${f(p[1])}`;
const add = (o, d, s) => [o[0] + d[0] * s, o[1] + d[1] * s];
const O = [ox, oy];

export function endpoints(sol) {
  const r = rays(sol);
  return {
    r,
    start: add(O, r.inc, -L),
    reflEnd: add(O, r.refl, L),
    transEnd: r.trans ? add(O, r.trans, L) : null,
  };
}

// arc from the normal (up: dir=-1, down: dir=+1) to angle phi on side sx
function arc(phiDeg, sx, dir, rad) {
  const p = phiDeg * DEG;
  const a = [ox, oy + dir * rad];
  const b = [ox + sx * rad * Math.sin(p), oy + dir * rad * Math.cos(p)];
  const sweep = (sx * dir < 0) ? 1 : 0;
  return `M${pt(a)} A${rad},${rad} 0 0 ${sweep} ${pt(b)}`;
}
// small angles: label sits just outside the ray, beyond the arc;
// large angles: label sits between ray and normal.
function arcLabel(phiDeg, sx, dir, _rad, text, cls) {
  let x, y, anchor;
  if (phiDeg < 42) {
    const h = 64;
    x = ox + sx * (h * Math.tan(phiDeg * DEG) + 7); y = oy + dir * h + 4;
    anchor = sx < 0 ? 'end' : 'start';
  } else {
    const m = (phiDeg / 2) * DEG;
    x = ox + sx * 80 * Math.sin(m); y = oy + dir * 80 * Math.cos(m) + 4; anchor = 'middle';
  }
  return `<text class="ang ${cls}" x="${f(x)}" y="${f(y)}" text-anchor="${anchor}">${text}</text>`;
}
function arrow(o, d, s, op) {
  const c = add(o, d, s), n = [-d[1], d[0]];
  const tip = add(c, d, 7), b1 = add(add(c, d, -5), n, 5), b2 = add(add(c, d, -5), n, -5);
  return `<path class="arrow" style="opacity:${op}" d="M${pt(tip)} L${pt(b1)} L${pt(b2)}Z"/>`;
}
const opac = (p) => f(0.18 + 0.82 * Math.sqrt(Math.max(0, p)));
const pct = (x) => `${fmt(100 * x, 1)} %`;
const sub = (s) => s;

export function drawScene(sol) {
  const e = endpoints(sol), r = e.r;
  const sh1 = f(0.05 + 0.32 * (sol.n1 - 1) / 1.5), sh2 = f(0.05 + 0.32 * (sol.n2 - 1) / 1.5);
  let s = '';
  s += `<rect class="med" x="0" y="0" width="400" height="${oy}" style="fill-opacity:${sh1}"/>`;
  s += `<rect class="med" x="0" y="${oy}" width="400" height="${360 - oy}" style="fill-opacity:${sh2}"/>`;
  s += `<line class="iface" x1="0" y1="${oy}" x2="400" y2="${oy}"/>`;
  s += `<text class="medlab" x="12" y="24">Meio 1 · n₁ = ${fmt(sol.n1, 2)}</text>`;
  s += `<text class="medlab" x="12" y="346">Meio 2 · n₂ = ${fmt(sol.n2, 2)}</text>`;
  s += `<text class="small" x="388" y="${oy - 7}" text-anchor="end">fronteira plana</text>`;
  // normal
  s += `<line class="normal" x1="${ox}" y1="${oy - 160}" x2="${ox}" y2="${oy + 160}"/>`;
  s += `<text class="small" x="${ox + 5}" y="${oy - 150}">normal</text>`;
  // critical-angle guides (only physically defined when n1 > n2)
  if (sol.critical !== null) {
    const c = sol.critical * DEG, R = 118;
    for (const sx of [-1, 1]) {
      const q = [ox + sx * R * Math.sin(c), oy - R * Math.cos(c)];
      s += `<line class="crit" x1="${ox}" y1="${oy}" x2="${f(q[0])}" y2="${f(q[1])}"/>`;
    }
    s += `<text class="small critlab" x="388" y="${oy - 22}" text-anchor="end">┄ ângulo crítico θc = ${fmt(sol.critical)}°</text>`;
  }
  // rays
  s += `<line class="ray" x1="${pt(e.start).replace(',', '" y1="')}" x2="${ox}" y2="${oy}"/>`;
  s += arrow(e.start, r.inc, L * 0.5, 1);
  s += `<line class="ray" style="opacity:${opac(sol.R)}" x1="${ox}" y1="${oy}" x2="${pt(e.reflEnd).replace(',', '" y2="')}"/>`;
  s += arrow(O, r.refl, L * 0.55, opac(sol.R));
  if (e.transEnd) {
    s += `<line class="ray" style="opacity:${opac(sol.T)}" x1="${ox}" y1="${oy}" x2="${pt(e.transEnd).replace(',', '" y2="')}"/>`;
    s += arrow(O, r.trans, L * 0.55, opac(sol.T));
    // undeviated continuation for comparison
    const g = add(O, r.inc, 90);
    s += `<line class="ghost" x1="${ox}" y1="${oy}" x2="${pt(g).replace(',', '" y2="')}"/>`;
  }
  // angle arcs
  const t1 = sol.theta1;
  if (t1 > 0.4) {
    s += `<path class="arc a1" d="${arc(t1, -1, -1, 46)}"/>` + arcLabel(t1, -1, -1, 62, `θ₁ ${fmt(t1)}°`, 'a1');
    s += `<path class="arc a1" d="${arc(t1, 1, -1, 46)}"/>` + arcLabel(t1, 1, -1, 62, `θᵣ ${fmt(t1)}°`, 'a1');
  }
  if (sol.theta2 !== null && sol.theta2 > 0.4) {
    s += `<path class="arc a2" d="${arc(sol.theta2, 1, 1, 46)}"/>` + arcLabel(sol.theta2, 1, 1, 64, `θ₂ ${fmt(sol.theta2)}°`, 'a2');
  }
  // ray labels at ends
  const lab = (p, d, name, val, op) => {
    const q = add(p, d, 24);
    const x = Math.min(370, Math.max(30, q[0])), y = Math.min(330, Math.max(40, q[1]));
    return `<text class="raylab" style="opacity:${Math.max(0.85, op)}" x="${f(x)}" y="${f(y)}" text-anchor="middle">${name}<tspan x="${f(x)}" dy="14" class="small">${val}</tspan></text>`;
  };
  s += lab(e.start, [-r.inc[0], -r.inc[1]], 'incidente', '100 %', 1);
  s += lab(e.reflEnd, r.refl, sol.tir ? 'refletido (RIT)' : 'refletido', `R = ${pct(sol.R)}`, opac(sol.R));
  if (e.transEnd) s += lab(e.transEnd, r.trans, 'transmitido', `T = ${pct(sol.T)}`, opac(sol.T));
  else s += `<text class="raylab tirnote" x="${ox + 70}" y="${oy + 40}">sem raio transmitido</text>`;
  s += `<circle class="opoint" cx="${ox}" cy="${oy}" r="3"/>`;
  return s;
}

export function drawPulses(sol, tau) {
  const e = endpoints(sol);
  let s = '';
  for (const p of pulses(sol, tau)) {
    let c;
    if (p.ray === 'inc') c = add(e.start, e.r.inc, p.s * L);
    else if (p.ray === 'refl') c = add(O, e.r.refl, p.s * L);
    else c = add(O, e.r.trans, p.s * L);
    const op = opac(p.power);
    s += `<circle class="halo" cx="${f(c[0])}" cy="${f(c[1])}" r="9" style="opacity:${f(op * 0.35)}"/>`;
    s += `<circle class="pulse" data-ray="${p.ray}" cx="${f(c[0])}" cy="${f(c[1])}" r="4.2" style="opacity:${op}"/>`;
  }
  return s;
}
